export class LexError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCTS = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

function isLetter(c) {
  return c !== undefined && /[A-Za-z]/.test(c)
}
function isDigit10(c) {
  return c !== undefined && /[0-9]/.test(c)
}
function isHex(c) {
  return c !== undefined && /[0-9a-fA-F]/.test(c)
}
function isBin(c) {
  return c === '0' || c === '1'
}
function isOct(c) {
  return c !== undefined && /[0-7]/.test(c)
}
function isIdentStart(c) {
  return c !== undefined && /[A-Za-z_]/.test(c)
}
function isIdentPart(c) {
  return c !== undefined && /[A-Za-z0-9_]/.test(c)
}
function validDigit(c, radix) {
  if (radix === 16) return isHex(c)
  if (radix === 2) return isBin(c)
  if (radix === 8) return isOct(c)
  return isDigit10(c)
}

class Lexer {
  constructor(input) {
    this.cps = Array.from(input)
    this.n = this.cps.length
    this.pos = 0
    this.line = 1
    this.col = 1
  }
  peek(o = 0) {
    return this.cps[this.pos + o]
  }
  atEnd() {
    return this.pos >= this.n
  }
  curPos() {
    return { line: this.line, col: this.col }
  }
  advance() {
    const cp = this.cps[this.pos++]
    if (cp === '\n') {
      this.line++
      this.col = 1
    } else if (cp === '\t') {
      this.col = (Math.floor((this.col - 1) / 4) + 1) * 4 + 1
    } else {
      this.col++
    }
    return cp
  }
}

function readDigitRun(lx, radix) {
  let result = ''
  let lastWasDigit = false
  for (;;) {
    const c = lx.peek()
    if (validDigit(c, radix)) {
      result += lx.advance()
      lastWasDigit = true
    } else if (c === '_' && lastWasDigit && validDigit(lx.peek(1), radix)) {
      result += lx.advance()
      lastWasDigit = false
    } else {
      break
    }
  }
  return result
}

function isTrailingInvalid(lx) {
  const c = lx.peek()
  return c !== undefined && (isLetter(c) || isDigit10(c) || c === '_')
}
function appendTrailing(lx, text) {
  while (isTrailingInvalid(lx)) text += lx.advance()
  return text
}

function scanNumber(lx) {
  const start = lx.curPos()
  let text = ''
  if (lx.peek() === '0' && ['x', 'X', 'b', 'B', 'o', 'O'].includes(lx.peek(1))) {
    text += lx.advance() // '0'
    const p = lx.advance()
    text += p
    const radix = p === 'x' || p === 'X' ? 16 : p === 'b' || p === 'B' ? 2 : 8
    const digits = readDigitRun(lx, radix)
    text += digits
    if (digits.length === 0 || isTrailingInvalid(lx)) {
      text = appendTrailing(lx, text)
      throw new LexError(start.line, start.col, `invalid number ${text}`)
    }
    return { line: start.line, col: start.col, kind: 'number', value: text }
  }

  const intPart = readDigitRun(lx, 10)
  text += intPart
  if (lx.peek() === '.' && isDigit10(lx.peek(1))) {
    text += lx.advance()
    text += readDigitRun(lx, 10)
  }
  if (lx.peek() === 'e' || lx.peek() === 'E') {
    const next1 = lx.peek(1)
    if (isDigit10(next1) || ((next1 === '+' || next1 === '-') && isDigit10(lx.peek(2)))) {
      text += lx.advance() // e/E
      if (lx.peek() === '+' || lx.peek() === '-') text += lx.advance()
      text += readDigitRun(lx, 10)
    }
  }
  if (isTrailingInvalid(lx)) {
    text = appendTrailing(lx, text)
    throw new LexError(start.line, start.col, `invalid number ${text}`)
  }
  return { line: start.line, col: start.col, kind: 'number', value: text }
}

function scanIdent(lx) {
  const start = lx.curPos()
  let text = lx.advance()
  while (isIdentPart(lx.peek())) text += lx.advance()
  const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
  return { line: start.line, col: start.col, kind, value: text }
}

function scanPunct(lx) {
  const start = lx.curPos()
  for (const p of PUNCTS) {
    const chars = Array.from(p)
    let match = true
    for (let i = 0; i < chars.length; i++) {
      if (lx.peek(i) !== chars[i]) {
        match = false
        break
      }
    }
    if (match) {
      let text = ''
      for (let i = 0; i < chars.length; i++) text += lx.advance()
      return { line: start.line, col: start.col, kind: 'punct', value: text }
    }
  }
  return null
}

function scanString(lx) {
  const start = lx.curPos()
  lx.advance() // opening quote
  let value = ''
  for (;;) {
    if (lx.atEnd()) throw new LexError(start.line, start.col, 'unterminated string')
    const c = lx.peek()
    if (c === '"') {
      lx.advance()
      break
    }
    if (c === '\n') {
      const p = lx.curPos()
      throw new LexError(p.line, p.col, 'newline in string')
    }
    if (c === '\\') {
      const bpos = lx.curPos()
      lx.advance() // backslash
      if (lx.atEnd()) throw new LexError(start.line, start.col, 'unterminated string')
      const e = lx.peek()
      if (e === 'n') {
        value += '\n'
        lx.advance()
      } else if (e === 't') {
        value += '\t'
        lx.advance()
      } else if (e === 'r') {
        value += '\r'
        lx.advance()
      } else if (e === '\\') {
        value += '\\'
        lx.advance()
      } else if (e === '"') {
        value += '"'
        lx.advance()
      } else if (e === '0') {
        value += '\0'
        lx.advance()
      } else if (e === 'x') {
        lx.advance() // x
        let hex = ''
        for (let i = 0; i < 2; i++) {
          if (!isHex(lx.peek())) throw new LexError(bpos.line, bpos.col, 'invalid escape \\x')
          if (lx.atEnd()) throw new LexError(start.line, start.col, 'unterminated string')
          hex += lx.advance()
        }
        value += String.fromCharCode(parseInt(hex, 16))
      } else if (e === 'u') {
        lx.advance() // u
        if (lx.peek() !== '{') throw new LexError(bpos.line, bpos.col, 'invalid escape \\u')
        lx.advance() // {
        let hex = ''
        while (isHex(lx.peek())) hex += lx.advance()
        if (hex.length === 0) throw new LexError(bpos.line, bpos.col, 'invalid escape \\u')
        if (lx.peek() !== '}') throw new LexError(bpos.line, bpos.col, 'invalid escape \\u')
        lx.advance() // }
        const cp = parseInt(hex, 16)
        if (cp > 0x10ffff) throw new LexError(bpos.line, bpos.col, 'invalid escape \\u')
        value += String.fromCodePoint(cp)
      } else {
        throw new LexError(bpos.line, bpos.col, `invalid escape \\${e}`)
      }
    } else {
      value += lx.advance()
    }
  }
  return { line: start.line, col: start.col, kind: 'string', value }
}

function scanRawString(lx) {
  const start = lx.curPos()
  lx.advance() // r
  lx.advance() // "
  let value = ''
  for (;;) {
    if (lx.atEnd()) throw new LexError(start.line, start.col, 'unterminated string')
    const c = lx.peek()
    if (c === '"') {
      lx.advance()
      break
    }
    value += lx.advance()
  }
  return { line: start.line, col: start.col, kind: 'rawstring', value }
}

export function tokenize(input) {
  const lx = new Lexer(input)
  const tokens = []
  while (!lx.atEnd()) {
    const c = lx.peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      lx.advance()
      continue
    }
    if (c === '/' && lx.peek(1) === '/') {
      lx.advance()
      lx.advance()
      while (!lx.atEnd() && lx.peek() !== '\n') lx.advance()
      continue
    }
    if (c === '/' && lx.peek(1) === '*') {
      const start = lx.curPos()
      lx.advance()
      lx.advance()
      let depth = 1
      while (depth > 0) {
        if (lx.atEnd()) throw new LexError(start.line, start.col, 'unterminated block comment')
        if (lx.peek() === '/' && lx.peek(1) === '*') {
          lx.advance()
          lx.advance()
          depth++
          continue
        }
        if (lx.peek() === '*' && lx.peek(1) === '/') {
          lx.advance()
          lx.advance()
          depth--
          continue
        }
        lx.advance()
      }
      continue
    }
    if (c === '"') {
      tokens.push(scanString(lx))
      continue
    }
    if (c === 'r' && lx.peek(1) === '"') {
      tokens.push(scanRawString(lx))
      continue
    }
    if (isIdentStart(c)) {
      tokens.push(scanIdent(lx))
      continue
    }
    if (isDigit10(c)) {
      tokens.push(scanNumber(lx))
      continue
    }
    const p = scanPunct(lx)
    if (p) {
      tokens.push(p)
      continue
    }
    const pos = lx.curPos()
    const ch = lx.advance()
    throw new LexError(pos.line, pos.col, `unexpected character ${ch}`)
  }
  return tokens
